@Service
class ZamowieniaProducent {
    private final KafkaTemplate<String, String> kafkaTemplate;

    ZamowieniaProducent(KafkaTemplate<String, String> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void wyslij(String idZamowienia, String tresc) {
        kafkaTemplate.send("zamowienia.topic", idZamowienia, tresc);
    }
}

@Component
class ZamowieniaOdbiorca {

    @KafkaListener(topics = "zamowienia.topic", groupId = "przetwarzanie-zamowien")
    public void naZamowienie(String tresc) {
        System.out.println("Odebrano przez Kafka: " + tresc);
    }
}

